revised = []
for item in notes:
    p = item["page"]
    item["diagramGuide"] = diagram.get(p, [])
    if p in (51, 75):
        item["interaction"] = {
            "type": "tap",
            "label": "Non-content slide: " + ("supplementary video link." if p == 51 else "reference list.")
        }
    else:
        q, opts, ans, exp = Q[p]
        item["interaction"] = {
            "type": "mcq", "q": q, "options": opts,
            "answer": ans, "explanation": exp
        }
    revised.append({
        "page": item["page"],
        "title": item["title"],
        "explain": item["explain"],
        "mustKnow": item["mustKnow"],
        "terms": item["terms"],
        "diagramGuide": item["diagramGuide"],
        "interaction": item["interaction"],
    })

out = ROOT / "revised-051-120.json"
out.write_text(json.dumps(revised, indent=2, ensure_ascii=False) + "\n")
